Edytor.Tekst:
public void Rozwiązanie_Odprawa_Emerytalno_Rentowa_Param(
    Soneta.Place.WypElementDodatek Element, WypSkladnik Składnik)
{
    // Element nienaliczany na realnej liście płac — wartości na planie rezerw
    // ustawia bezpośrednio algorytm DefinicjaPlanowanejListyPłac (KopiujElement).
    Składnik.Podstawa1 = DoubleCy.Zero;
}

public Currency Rozwiązanie_Odprawa_Emerytalno_Rentowa_Wylicz(
    Soneta.Place.WypElementDodatek Element, WypSkladnik Składnik)
{
    return Currency.Zero;
}

DefinicjaPlanowanejListyPłac.Algorytm:
public override SourceFilterDelegate FiltrNaliczania {
    get { return new SourceFilterDelegate(SourceFilter); }
}

bool SourceFilter(object sender, SourceFilterArgs args) {
    return args.Element.Wartosc != 0;
}

protected override void KopiujNagłówek(PlanowanaWypłata dest, Soneta.Place.Wyplata src) {
    // Nadpisujemy domyślne "dest.Wartosc = src.Wartosc" (suma CAŁEJ wypłaty) —
    // interesuje nas wyłącznie suma skopiowanych (odwróconych) niżej pozycji.
    dest.Wartosc = 0;
}

protected override void KopiujElementy(PlanowanaWypłata dest, Soneta.Place.Wyplata src) {
    DefinicjaElementu rozwiazanie = dest.Module.DefElementow.WgNazwy["Rozwiązanie odprawa emerytalno-rentowa"];

    foreach (WypElement item in src.Elementy)
        if (item.Definicja.Nazwa == "Odprawa emerytalna" && item.Wartosc != 0) {
            PlanowanyElementWypłaty plan = new PlanowanyElementWypłaty(dest, rozwiazanie, item);
            dest.Module.PlanElementyWyp.AddRow(plan);
            KopiujElement(plan, item);
            dest.Wartosc += plan.Wartosc;
        }
}

protected override void KopiujElement(PlanowanyElementWypłaty dest, WypElement src) {
    // Odwrócenie znaku ("rozwiązanie" wcześniej rozliczonej odprawy) — w
    // przeciwieństwie do bazowej implementacji (zwykła kopia 1:1, bez zmiany
    // znaku, pod tą samą Definicją).
    dest.Wartosc = -src.Wartosc;
    dest.Brutto = -src.DoOpodatkowania;
    dest.Narzuty = -src.Podatki.Narzuty;
    dest.Koszty = -src.Podatki.KosztyRazem;

    // Podatki.KopiujNaMinus neguje wszystkie pola składkowo-podatkowe. Bazowy
    // kod woła ją DWA razy (podwójna negacja = zwykła kopia) — tu wołamy RAZ,
    // żeby faktycznie odwrócić znak.
    dest.Podatki.KopiujNaMinus(src.Podatki);
    dest.RodzajSkladki = src.RodzajSkladki;

    if (src.SkładnikGłówny != null) {
        if (src.Definicja.Algorytm.ElPodstawa1 != "") dest.Podstawa1 -= src.SkładnikGłówny.Podstawa1;
        if (src.Definicja.Algorytm.ElPodstawa2 != "") dest.Podstawa2 -= src.SkładnikGłówny.Podstawa2;
        if (src.Definicja.Algorytm.ElPodstawa3 != "") dest.Podstawa3 -= src.SkładnikGłówny.Podstawa3;
        if (src.Definicja.Algorytm.ElPodstawa4 != "") dest.Podstawa4 -= src.SkładnikGłówny.Podstawa4;
        if (src.Definicja.Algorytm.ElPodstawa5 != "") dest.Podstawa5 -= src.SkładnikGłówny.Podstawa5;
        // Czas/Dni to metadane godzin/dni (nie kwoty) — kopiowane addytywnie,
        // bez zmiany znaku, tak jak w implementacji bazowej.
        if (src.Definicja.Algorytm.ElCzas != "") dest.Czas += src.SkładnikGłówny.Czas;
        if (src.Definicja.Algorytm.ElDni != "") dest.Dni += src.SkładnikGłówny.Dni;
    }

    if (!src.ZapisObliczen.IsEmpty)
        dest.ZapisObliczen = src.ZapisObliczen;
}
